import{_ as a,c as p,a as n,o as r}from"./app-BzZwWvKp.js";const d={};function i(c,e){return r(),p("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-13-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-13-资讯日报"><span>2026-11-13 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="黄仁勋即刻辞去英伟达ceo职务" tabindex="-1"><a class="header-anchor" href="#黄仁勋即刻辞去英伟达ceo职务"><span>黄仁勋即刻辞去英伟达CEO职务</span></a></h3><p>英伟达宣布黄仁勋辞去总裁兼CEO及董事职务，即刻生效。现任CFO科莱特·克雷斯出任临时CEO，董事会已启动新CEO遴选，并任命Harvey Jones为首任董事长。<a href="https://mp.weixin.qq.com/s?__biz=Mzg4MjYyMzUyNw==&amp;chksm=cebdb717a069d64b53a9356ff285de0b8eb2054c311c70e453919730c4e4d7a2c02734917b51&amp;idx=1&amp;mid=2247521633&amp;sn=7e04c354a3cf28fbdd57ac842456a6c6" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="character-ai-申请破产保护" tabindex="-1"><a class="header-anchor" href="#character-ai-申请破产保护"><span>Character.AI 申请破产保护</span></a></h3><p>曾估值 10 亿美元的 AI 角色平台 Character.AI 正式申请破产保护，因算力消耗沉重致月亏损近 900 万美元；而转向游戏化付费的同行已实现盈利。</p><p>亏损根源：月运营费 1330 万美元，算力支出占 45%</p><p>赛道逆势：AI陪伴移动端月收入翻倍至 6.56 亿元</p><p>盈利样本：韩国 Zeta 靠互动剧情上半年营收 3.4 亿元<a href="https://mp.weixin.qq.com/s?__biz=MzkyNTY1MjE2OA==&amp;chksm=c05565ac2ed624c6d3e60751060ed940b6b16b8abc3e05b337ff71c853c8423c44d1e23597ec&amp;idx=1&amp;mid=2247494683&amp;sn=21ee314e3623951151e5debc111ff131" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="北京具身智能新政-整机年产能达20万台" tabindex="-1"><a class="header-anchor" href="#北京具身智能新政-整机年产能达20万台"><span>北京具身智能新政：整机年产能达20万台</span></a></h3><p>北京发布具身智能三年方案，提出到 2028 年形成年产 20 万台整机生产能力，新增超 50000 PFlops 专用算力，并对紧缺人才支持落户与住房。</p><p>算力与数据：新增超50000P专用算力并采百万小时数据</p><p>人才支持：对领域急需紧缺人才提供落户、住房和就医保障</p><p>硬件指标：灵巧手单只成本万元内且连续作业续航超4小时<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=853b3c63f7da11f4a4e06dd652ca8e66511d715ab23aaced5ed62abab5c8d1efab539906f50b&amp;idx=2&amp;mid=2652813845&amp;sn=81361d05e46bfd66c9c4268672fbbc98" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="deepmind发布基因组模型alphagenome-2" tabindex="-1"><a class="header-anchor" href="#deepmind发布基因组模型alphagenome-2"><span>DeepMind发布基因组模型AlphaGenome 2</span></a></h3><p>Google DeepMind 发布基因组模型 AlphaGenome 2，能针对具体细胞状态预测 DNA 变异影响，因果变异识别率达 30%，是上一代模型的近两倍。</p><p>训练数据：涵盖人类和小鼠逾1.07亿份细胞数据</p><p>适配能力：面对新单细胞实验数据无需重新训练</p><p>预测模态：在基因表达外新增DNA甲基化预测<a href="https://mp.weixin.qq.com/s?__biz=MzI3MjM3ODk0NQ==&amp;chksm=eab698c97033c93193a2dea4aa06ed8376feec195484648b0970ca5ac8cde99bd8724fe76820&amp;idx=1&amp;mid=2247514368&amp;sn=9c572e1a441163661c072db8e3a9e188" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="谷歌发布hydrogen小模型-速度提升2-5倍" tabindex="-1"><a class="header-anchor" href="#谷歌发布hydrogen小模型-速度提升2-5倍"><span>谷歌发布Hydrogen小模型：速度提升2.5倍</span></a></h3><p>谷歌发布轻量模型 Gemini 4 Hydrogen，接替上一代 Flash 模型，任务完成速度提升2.5倍，已在全球陆续上线 API、Gemini App 及搜索入口。</p><p>定价：百万输入Token收1.5美元，输出收7.5美元</p><p>协同：搭配大模型调度可减少24%消耗并提速19%</p><p>性能：代码缺陷修复与长程Agent评测得分均超竞品<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e988dbfbfb27b312ddcfad4a348f69cddc8cba1322d2f8670ca57e58dbeb2b3968a1d635e160&amp;idx=3&amp;mid=2247943733&amp;sn=745bfc3f58406752d2d63db1306d234c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="qwen4-max预览版上线qoder限时2折" tabindex="-1"><a class="header-anchor" href="#qwen4-max预览版上线qoder限时2折"><span>Qwen4-Max预览版上线Qoder限时2折</span></a></h3><p>阿里大模型 Qwen4-Max 预览版在编程工具 Qoder 上线，主打代码与复杂任务交付，目前在 Qoder 限时两折可用，预览期至 11 月 25 日。</p><p>交付完整：单句需求可直接生成交互式 3D 网页与小游戏</p><p>速度偏慢：默认开启高强度深度思考，复杂任务耗时较长</p><p>稳定性：社区测试通过率有波动，适合大块任务而非简单改写<a href="https://mp.weixin.qq.com/s?__biz=MzU2Njg0OTEyNQ==&amp;chksm=fdc938b7c62b7cd4170a7bdb6a06c1b754da3f9681e4a82e779867808e11fd56218347cb2197&amp;idx=1&amp;mid=2247498108&amp;sn=a957da08a6306b15efdb8b340061392c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="百度萝卜快跑联合神州推无人自驾游" tabindex="-1"><a class="header-anchor" href="#百度萝卜快跑联合神州推无人自驾游"><span>百度萝卜快跑联合神州推无人自驾游</span></a></h3><p>百度 Apollo 联合神州租车在海南推出 L4 级无人驾驶租车自驾游服务，用户可按小时或按天租用车辆，全流程支持自动取车、多目的地出行与自动还车。</p><p>累计超2300万单且全无人里程2.4亿公里</p><p>发布Apollo World用于训练</p><p>日均生成10万公里仿真里程<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=ff61e22842937b8765147f60d036e52cd0423379f2e8cc7cf82e1352687c80090ba7ec112625&amp;idx=1&amp;mid=2247560226&amp;sn=33179e6fb9e70161930786798b1e2c1c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="百度上线大模型交易平台词元所" tabindex="-1"><a class="header-anchor" href="#百度上线大模型交易平台词元所"><span>百度上线大模型交易平台词元所</span></a></h3><p>百度创始人李彦宏在百度世界大会上表示，未来岗位将收敛为负责创造的 Builder 与负责沟通的 Seller 两类，并正式推出大模型交易平台「词元所」。</p><p>运营数据：萝卜快跑全无人驾驶里程已超过2.4亿公里</p><p>算力趋势：推理计算将成为AI芯片增长的主要动力<a href="https://mp.weixin.qq.com/s?__biz=MzI5NzUyMzM1Mg==&amp;chksm=ed2c1af693b1fab4f8ba8ee1bfc1dc61a493e7d5b666d71d7fc7b0ecbea79e672fb2647a83db&amp;idx=1&amp;mid=2247670691&amp;sn=d7f5b926c20c9789e78987946dd3fed9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="xai-发布-grok-bot-1-0-团队版" tabindex="-1"><a class="header-anchor" href="#xai-发布-grok-bot-1-0-团队版"><span>xAI 发布 Grok Bot 1.0 团队版</span></a></h3><p>马斯克旗下的 xAI 正式发布 Grok Bot 1.0，核心升级为支持团队多人共享的 AI 助手，能接入 Slack、Teams 和视频会议，并主动认领工作。</p><p>工作方式：每台 Bot 配有云端电脑可跨应用操作界面</p><p>可用范围：macOS 客户端上线，面向团队和企业套餐用户<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85831a075f1f7b58d2e8c09e2f500762fcc31b4e765fd16886b1ff3f5292e46b049121763014&amp;idx=2&amp;mid=2651074135&amp;sn=2019b2d7e4f158bb07852a889f5a7b17" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="豆包工作接入-kimi-与-deepseek-等模型" tabindex="-1"><a class="header-anchor" href="#豆包工作接入-kimi-与-deepseek-等模型"><span>豆包工作接入 Kimi 与 DeepSeek 等模型</span></a></h3><p>豆包工作宣布正式接入 Kimi、GLM 等第三方模型，并在页面标注各模型的额度消耗倍率。平台还推出限时优惠，下调部分模型的额度消耗倍率。<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODIzNTc2MA==&amp;chksm=bcfdf18da49d0e476376897c4c6864477836d0ba8000e89da5a645567b77e1442f16d78b19f4&amp;idx=2&amp;mid=2661080233&amp;sn=b63e883ff96dab7545daee170e0d03f2" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="ai-agent-架构整理出-26-种设计模式" tabindex="-1"><a class="header-anchor" href="#ai-agent-架构整理出-26-种设计模式"><span>AI Agent 架构整理出 26 种设计模式</span></a></h3><p>行业目录梳理出 AI Agent 系统的 26 种设计模式，涵盖认知、结构、协作与运行四大类，指出大模型本身缺乏可靠调度，必须依靠外部工程框架管理状态与安全。</p><p>认知与结构：涵盖 ReAct 循环、代码执行与分层记忆</p><p>协作与调度：支持中心编排、去中心化共享及对抗辩论</p><p>生产级运行：引入确定性安全护栏、人工检查点与持久执行<a href="https://mp.weixin.qq.com/s?__biz=MzIwNDA5NDYzNA==&amp;chksm=97e9ac8abbfa4d6b8fcb765d65f3ef5a69aebe5e1e5642a2281519f0752d67393feb70a162d5&amp;idx=1&amp;mid=2247513103&amp;sn=c4dc887c4963cc9d7b3046f712e6bdc0" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai-管理工作或比基层更早自动化" tabindex="-1"><a class="header-anchor" href="#openai-管理工作或比基层更早自动化"><span>OpenAI：管理工作或比基层更早自动化</span></a></h3><p>OpenAI 官网发文探讨组织形态演进，提出部分管理工作或比基层更早自动化：管理者日常多为信息汇总与协调，相比涉及物理操作的基层更易被 Agent 拆解替代。</p><p>组织形态：划分为员工助手、人机并列协作及高管决策协调层三种</p><p>决策影响：AI持异见时60%分析师动摇，近八成借用其论据</p><p>企业落地：Uber已向3万人部署，Oracle调研耗时缩至20分<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=fae9440109ec8e65e7182a5fa2c74d745d5cf28d4d3ef1454f1a5f45736ed02e4b87a066ec4f&amp;idx=3&amp;mid=2247783813&amp;sn=72905a89b32d1a0eb95534207e046958" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="开源-hyperflow-将-33b-视频模型压至-14b" tabindex="-1"><a class="header-anchor" href="#开源-hyperflow-将-33b-视频模型压至-14b"><span>开源 HyperFlow 将 33B 视频模型压至 14B</span></a></h3><p>开发团队 Video Rebirth 开源 HyperFlow H3 Flash，将 MiniMax 的 33B 视频模型压缩至 13.7B 并支持 6 步采样，24GB 显存显卡即可运行。</p><p>压缩方案：通过时间嵌入降维、SVD 白化与旋转 INT8 实现轻量化</p><p>运行门槛：提供 GGUF 格式，支持 ComfyUI，单张 4090 可跑</p><p>长片能力：配套框架支持用一张参考图生成 60 分钟连续视频<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MDQyNTY4Mw==&amp;chksm=c3082a3375990ee582e18477ad94eee64379606897baa97c7a54067ce7dd0b897fa7c9ba0ae5&amp;idx=1&amp;mid=2247496857&amp;sn=4f0bd8a29ad2bd789f1ae82505362002" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="厦大吉大开源智能体记忆系统evomemstate" tabindex="-1"><a class="header-anchor" href="#厦大吉大开源智能体记忆系统evomemstate"><span>厦大吉大开源智能体记忆系统EvoMemState</span></a></h3><p>厦门大学与吉林大学等团队提出并开源智能体长期记忆系统 EvoMemState，在传统事实存储外引入动态关系与推理状态，基准测试准确率超最强基线最高12.2个百分点。</p><p>机制：划分为持久事实、关系状态与请求级推理三层</p><p>演化：基于强化学习根据回答质量学习记忆使用策略</p><p>检索：平均完整检索率达到85.6%<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3a53dda1bc577dbc0d36d3a3ccecc133d5be8513d177a8c9d121bc319f378c735135ee9971b&amp;idx=2&amp;mid=2247513618&amp;sn=8150689ffc297a6f968be3bd09d338f8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="清华伯克利开源具身框架-qwen操控机器人超闭源模型" tabindex="-1"><a class="header-anchor" href="#清华伯克利开源具身框架-qwen操控机器人超闭源模型"><span>清华伯克利开源具身框架，Qwen操控机器人超闭源模型</span></a></h3><p>清华与 UC 伯克利开源机器人智能体框架 uni-robot-agent。开源模型 Qwen 搭配该框架在 RoboDojo 评测中拿下 31.39 分反超 GPT-6 Astra，单局成本仅为其二十分之一。</p><p>真机表现：19项桌面任务零样本得53.5分，超越微调策略π0.5</p><p>核心设计：统一工具接口且不依赖仿真特权信息，支持流水线并发</p><p>规律发现：模型大不等于会用机器人，关键在空间定位与几何计算<a href="https://mp.weixin.qq.com/s?__biz=MzIwNzc2NTk0NQ==&amp;chksm=96553fa26145effeaeedb60ef7b49d102cf2a6c468ca2183b8dae9f01fb2c8880d28aa7adebb&amp;idx=1&amp;mid=2247623315&amp;sn=b9a8f27073c3ae139fa64fce04756624" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="testprism-ai写测试合格率跌破30" tabindex="-1"><a class="header-anchor" href="#testprism-ai写测试合格率跌破30"><span>TestPrism，AI写测试合格率跌破30%</span></a></h3><p>南京大学团队发布代码测试评测基准 TestPrism。评测发现，面对同一需求的多样代码实现时，最强 Coding Agent 的联合测试成功率仅 28%。</p><p>失败原因：过拟合与判断标准错误占半数</p><p>提升方案：TestHelix通过多Agent交叉检验提升约12%</p><p>资源获取：评测基准数据与相关代码已在GitHub开源<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0c27f9758c3931b7922696a81c46da1ba5163d8adc2006523f3a3233d23a54fc455eaa049c8&amp;idx=3&amp;mid=2652742394&amp;sn=83658d4b00ddad5b7c7b414c0a4b64f4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openrsi让8个模型吞吐最高提速326" tabindex="-1"><a class="header-anchor" href="#openrsi让8个模型吞吐最高提速326"><span>OpenRSI让8个模型吞吐最高提速326%</span></a></h3><p>OpenRSI 联合 SGLang-Omni 推出自动化优化框架，在 H100 上将 8 个语音多模态模型的吞吐提升了 7.6% 至 326.5%，14 个 PR 已全部被官方合入。</p><p>协作模式：人类负责定义目标，Agent负责实验调优</p><p>优化方向：消除线程空转、跳过冗余计算与机器异步流水线</p><p>开源情况：自动化评测与数据管道已在 GitHub 开源<a href="https://mp.weixin.qq.com/s?__biz=MzA4MjY4NTk0NQ==&amp;chksm=9e1302ac9dc97d82618dd8f76f9e74e17b6c25b3b2599aa4d1331cf3485aa234ccbc4b11984f&amp;idx=1&amp;mid=2247532764&amp;sn=809deb181cf36a33c7154457be4f98c9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="deepmind评测-ai攻坚任务最高仅56-6" tabindex="-1"><a class="header-anchor" href="#deepmind评测-ai攻坚任务最高仅56-6"><span>DeepMind评测：AI攻坚任务最高仅56.6%</span></a></h3><p>Google DeepMind 推出多模态评测基准 MKA，覆盖 10 个领域的 200 项端到端专业工作任务。测试显示参评模型在较难的攻坚项上最高仅达 56.6%。</p><p>任务设计：涵盖83种职业的图纸与表格等1459份文件</p><p>成本差异：交付质量相近下单次任务费用相差逾6倍</p><p>视觉依赖：剥离看图工具后部分案例得分骤降<a href="https://mp.weixin.qq.com/s?__biz=MzU3NTQ2NDIyOQ==&amp;chksm=fc19ef32f494d8af0cef2f8ad38b4fbe69723831151129c04d8b43e7a3b7c3871359c0626a24&amp;idx=1&amp;mid=2247531378&amp;sn=43703072d04cbe7df724d390ec7a141b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="未来医生medgpt以88比12胜过三甲医生" tabindex="-1"><a class="header-anchor" href="#未来医生medgpt以88比12胜过三甲医生"><span>未来医生MedGPT以88比12胜过三甲医生</span></a></h3><p>在40例复杂肺癌病例盲评中，未来医生MedGPT以85.29分对53.26分、88比12的胜率 战胜250名三甲医院医生，且AI答卷长度比医生精简四成以上。</p><p>架构机制：自建800万结构化证据库并引入虚拟患者推演与对抗审查</p><p>消融实验：若脱离多智能体协作与审查流程直接裸跑底模成绩跌24分</p><p>辅助效果：医生参考其策略报告后综合决策评分由53.4升至66.27<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0f158d3dc4a8cb5ea7fbc1d6a370facf9db6c538d8b855cb50b02714d48362fe935d1bf1ad2&amp;idx=1&amp;mid=2652742394&amp;sn=578bf5c6b8b6e59b99b01953e0c3f53a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="fireflash-64卡5天训出顶尖智能体" tabindex="-1"><a class="header-anchor" href="#fireflash-64卡5天训出顶尖智能体"><span>FireFlash：64卡5天训出顶尖智能体</span></a></h3><p>UCLA 等发布 FireFlash，基于 GLM-5.3-Flash 仅用 64 张 B300 训练不到 5 天，单任务推理成本低30倍以上。</p><p>异步解耦训练与采样，利用陈旧FP8样本降低开销</p><p>仅保留通过率15%至85%的任务，零信号组降至10%</p><p>单次试验花费0.72美元，所有更高分模型成本翻倍<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85c2ff6ec388e6b2820ed18ba7f5d26a82feda9a077fd86501e2f366157316014d535417bfb3&amp;idx=3&amp;mid=2651074135&amp;sn=f702c61a40c6ebe66be517d551e8d6b6" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',101)]))}const s=a(d,[["render",i]]),l=JSON.parse('{"path":"/posts/2026-11-13.html","title":"AI日报：黄仁勋即刻辞去英伟达CEO职务; Character.AI 申请破产保护; 北京具身智能新政：整机年产能达20万台","lang":"zh-CN","frontmatter":{"date":"2026-11-13T00:00:00.000Z","title":"AI日报：黄仁勋即刻辞去英伟达CEO职务; Character.AI 申请破产保护; 北京具身智能新政：整机年产能达20万台"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"黄仁勋即刻辞去英伟达CEO职务","slug":"黄仁勋即刻辞去英伟达ceo职务","link":"#黄仁勋即刻辞去英伟达ceo职务","children":[]},{"level":3,"title":"Character.AI 申请破产保护","slug":"character-ai-申请破产保护","link":"#character-ai-申请破产保护","children":[]},{"level":3,"title":"北京具身智能新政：整机年产能达20万台","slug":"北京具身智能新政-整机年产能达20万台","link":"#北京具身智能新政-整机年产能达20万台","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"DeepMind发布基因组模型AlphaGenome 2","slug":"deepmind发布基因组模型alphagenome-2","link":"#deepmind发布基因组模型alphagenome-2","children":[]},{"level":3,"title":"谷歌发布Hydrogen小模型：速度提升2.5倍","slug":"谷歌发布hydrogen小模型-速度提升2-5倍","link":"#谷歌发布hydrogen小模型-速度提升2-5倍","children":[]},{"level":3,"title":"Qwen4-Max预览版上线Qoder限时2折","slug":"qwen4-max预览版上线qoder限时2折","link":"#qwen4-max预览版上线qoder限时2折","children":[]},{"level":3,"title":"百度萝卜快跑联合神州推无人自驾游","slug":"百度萝卜快跑联合神州推无人自驾游","link":"#百度萝卜快跑联合神州推无人自驾游","children":[]},{"level":3,"title":"百度上线大模型交易平台词元所","slug":"百度上线大模型交易平台词元所","link":"#百度上线大模型交易平台词元所","children":[]},{"level":3,"title":"xAI 发布 Grok Bot 1.0 团队版","slug":"xai-发布-grok-bot-1-0-团队版","link":"#xai-发布-grok-bot-1-0-团队版","children":[]},{"level":3,"title":"豆包工作接入 Kimi 与 DeepSeek 等模型","slug":"豆包工作接入-kimi-与-deepseek-等模型","link":"#豆包工作接入-kimi-与-deepseek-等模型","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"AI Agent 架构整理出 26 种设计模式","slug":"ai-agent-架构整理出-26-种设计模式","link":"#ai-agent-架构整理出-26-种设计模式","children":[]},{"level":3,"title":"OpenAI：管理工作或比基层更早自动化","slug":"openai-管理工作或比基层更早自动化","link":"#openai-管理工作或比基层更早自动化","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"开源 HyperFlow 将 33B 视频模型压至 14B","slug":"开源-hyperflow-将-33b-视频模型压至-14b","link":"#开源-hyperflow-将-33b-视频模型压至-14b","children":[]},{"level":3,"title":"厦大吉大开源智能体记忆系统EvoMemState","slug":"厦大吉大开源智能体记忆系统evomemstate","link":"#厦大吉大开源智能体记忆系统evomemstate","children":[]},{"level":3,"title":"清华伯克利开源具身框架，Qwen操控机器人超闭源模型","slug":"清华伯克利开源具身框架-qwen操控机器人超闭源模型","link":"#清华伯克利开源具身框架-qwen操控机器人超闭源模型","children":[]},{"level":3,"title":"TestPrism，AI写测试合格率跌破30%","slug":"testprism-ai写测试合格率跌破30","link":"#testprism-ai写测试合格率跌破30","children":[]},{"level":3,"title":"OpenRSI让8个模型吞吐最高提速326%","slug":"openrsi让8个模型吞吐最高提速326","link":"#openrsi让8个模型吞吐最高提速326","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"DeepMind评测：AI攻坚任务最高仅56.6%","slug":"deepmind评测-ai攻坚任务最高仅56-6","link":"#deepmind评测-ai攻坚任务最高仅56-6","children":[]},{"level":3,"title":"未来医生MedGPT以88比12胜过三甲医生","slug":"未来医生medgpt以88比12胜过三甲医生","link":"#未来医生medgpt以88比12胜过三甲医生","children":[]},{"level":3,"title":"FireFlash：64卡5天训出顶尖智能体","slug":"fireflash-64卡5天训出顶尖智能体","link":"#fireflash-64卡5天训出顶尖智能体","children":[]}]}],"git":{},"filePathRelative":"posts/2026-11-13.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-13 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>黄仁勋即刻辞去英伟达CEO职务</h3>\\n<p>英伟达宣布黄仁勋辞去总裁兼CEO及董事职务，即刻生效。现任CFO科莱特·克雷斯出任临时CEO，董事会已启动新CEO遴选，并任命Harvey Jones为首任董事长。<a href=\\"https://mp.weixin.qq.com/s?__biz=Mzg4MjYyMzUyNw==&amp;chksm=cebdb717a069d64b53a9356ff285de0b8eb2054c311c70e453919730c4e4d7a2c02734917b51&amp;idx=1&amp;mid=2247521633&amp;sn=7e04c354a3cf28fbdd57ac842456a6c6\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{s as comp,l as data};
